import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  navigationMenuArrowClassName,
  navigationMenuContentClassName,
  navigationMenuItemClassName,
  navigationMenuLinkClassName,
  navigationMenuListClassName,
  navigationMenuPopupClassName,
  navigationMenuPortalClassName,
  navigationMenuPositionerClassName,
  navigationMenuRootClassName,
  navigationMenuTriggerClassName,
  navigationMenuViewportClassName,
} from "./view";

export {
  navigationMenuArrowClassName,
  navigationMenuContentClassName,
  navigationMenuItemClassName,
  navigationMenuLinkClassName,
  navigationMenuListClassName,
  navigationMenuPopupClassName,
  navigationMenuPortalClassName,
  navigationMenuPositionerClassName,
  navigationMenuRootClassName,
  navigationMenuTriggerClassName,
  navigationMenuViewportClassName,
} from "./view";

export type NavigationMenuStyle = Readonly<Record<string, string>>;

export type PartViewConfig = Readonly<{
  children: readonly Html[];
  className?: string | undefined;
  style?: NavigationMenuStyle | undefined;
}>;

export type TriggerViewConfig<ParentMessage> = Readonly<{
  open: boolean;
  onToggle: ParentMessage;
  children: readonly Html[];
  className?: string | undefined;
  style?: NavigationMenuStyle | undefined;
}>;

export type LinkViewConfig = Readonly<{
  href: string;
  children: readonly Html[];
  className?: string | undefined;
  style?: NavigationMenuStyle | undefined;
}>;

export type PortalViewConfig = Readonly<{
  open: boolean;
  children: readonly Html[];
  className?: string | undefined;
  style?: NavigationMenuStyle | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const divPartView = <ParentMessage>(
  baseClassName: string,
  { children, className, style }: PartViewConfig
): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(baseClassName, className)),
    ],
    children
  );
};

export const rootView = <ParentMessage>(config: PartViewConfig): Html =>
  divPartView<ParentMessage>(navigationMenuRootClassName, config);

export const listView = <ParentMessage>(config: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.nav(
    [
      h.Attribute("aria-label", "Main navigation"),
      h.Class(classNames(navigationMenuListClassName, config.className)),
      ...(config.style === undefined ? [] : [h.Style(config.style)]),
    ],
    config.children
  );
};

export const itemView = <ParentMessage>(config: PartViewConfig): Html =>
  divPartView<ParentMessage>(navigationMenuItemClassName, config);

export const triggerView = <ParentMessage>({
  open,
  onToggle,
  children,
  className,
  style,
}: TriggerViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.Attribute("aria-expanded", open ? "true" : "false"),
      h.Attribute("aria-haspopup", "menu"),
      ...(open ? [h.Attribute("data-open", "")] : []),
      h.OnClick(onToggle),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(navigationMenuTriggerClassName, className)),
    ],
    children
  );
};

export const linkView = <ParentMessage>({
  href,
  children,
  className,
  style,
}: LinkViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.a(
    [
      h.Href(href),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(navigationMenuLinkClassName, className)),
    ],
    children
  );
};

export const portalView = <ParentMessage>({
  open,
  children,
  className,
  style,
}: PortalViewConfig): Html => {
  const h = html<ParentMessage>();

  if (!open) {
    return h.div([h.Hidden(true)], []);
  }

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(navigationMenuPortalClassName, className)),
    ],
    children
  );
};

export const positionerView = <ParentMessage>(config: PartViewConfig): Html =>
  divPartView<ParentMessage>(navigationMenuPositionerClassName, config);

export const popupView = <ParentMessage>(config: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "menu"),
      ...(config.style === undefined ? [] : [h.Style(config.style)]),
      h.Class(classNames(navigationMenuPopupClassName, config.className)),
    ],
    config.children
  );
};

export const viewportView = <ParentMessage>(config: PartViewConfig): Html =>
  divPartView<ParentMessage>(navigationMenuViewportClassName, config);

export const contentView = <ParentMessage>(config: PartViewConfig): Html =>
  divPartView<ParentMessage>(navigationMenuContentClassName, config);

export const arrowView = <ParentMessage>({
  className,
  style,
}: Omit<PartViewConfig, "children">): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.AriaHidden(true),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(navigationMenuArrowClassName, className)),
    ],
    []
  );
};

export const navigationMenuRootClassName = "relative z-10";

export const navigationMenuListClassName =
  "flex items-center gap-1 rounded-lg border border-gray-200 bg-white p-1 shadow-sm";

export const navigationMenuItemClassName = "relative";

export const navigationMenuTriggerClassName =
  "inline-flex items-center justify-center rounded-md px-3 py-2 text-base font-medium text-gray-700 transition hover:bg-gray-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600 data-[open]:bg-gray-100";

export const navigationMenuLinkClassName =
  "inline-flex items-center justify-center rounded-md px-3 py-2 text-base font-medium text-gray-700 transition hover:bg-gray-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600";

export const navigationMenuPortalClassName = "contents";

export const navigationMenuPositionerClassName =
  "absolute left-0 top-full mt-2";

export const navigationMenuPopupClassName =
  "w-[34rem] overflow-hidden rounded-lg border border-gray-200 bg-white p-4 shadow-lg";

export const navigationMenuViewportClassName = "grid gap-3 md:grid-cols-2";

export const navigationMenuContentClassName =
  "rounded-lg border border-gray-100 bg-gray-50 p-4";

export const navigationMenuArrowClassName =
  "absolute -top-1 left-8 size-3 rotate-45 border-l border-t border-gray-200 bg-white";

import { Scene } from "foldkit";
import { html } from "foldkit/html";
import { describe, expect, test } from "vitest";

import * as NavigationMenu from ".";

const view = (open: boolean) => {
  const h = html<boolean>();

  return NavigationMenu.rootView<boolean>({
    children: [
      NavigationMenu.listView<boolean>({
        children: [
          NavigationMenu.itemView<boolean>({
            children: [
              NavigationMenu.triggerView<boolean>({
                open,
                onToggle: !open,
                children: [h.span([], ["Overview"])],
              }),
            ],
          }),
        ],
      }),
      NavigationMenu.portalView<boolean>({
        open,
        children: [
          NavigationMenu.positionerView<boolean>({
            children: [
              NavigationMenu.popupView<boolean>({
                children: [
                  NavigationMenu.arrowView<boolean>({}),
                  NavigationMenu.viewportView<boolean>({
                    children: [
                      NavigationMenu.contentView<boolean>({
                        children: [h.span([], ["Introduction"])],
                      }),
                    ],
                  }),
                ],
              }),
            ],
          }),
        ],
      }),
    ],
  });
};

describe("Navigation Menu registry component", () => {
  test("renders controlled trigger and popup anatomy", () => {
    Scene.scene(
      {
        update: (_model: boolean, message: boolean) => [message, []] as const,
        view,
      },
      Scene.with(false),
      Scene.expect(Scene.role("button", { name: "Overview" })).toHaveAttr(
        "aria-expanded",
        "false"
      ),
      Scene.expect(Scene.role("menu")).not.toExist(),
      Scene.click(Scene.role("button", { name: "Overview" })),
      Scene.expect(Scene.role("button", { name: "Overview" })).toHaveAttr(
        "aria-expanded",
        "true"
      ),
      Scene.expect(Scene.role("menu")).toExist(),
      Scene.expect(Scene.text("Introduction")).toExist()
    );
  });

  test("exports Base UI navigation menu class hooks", () => {
    expect(NavigationMenu.navigationMenuRootClassName).toContain("relative");
    expect(NavigationMenu.navigationMenuTriggerClassName).toContain(
      "data-[open]"
    );
    expect(NavigationMenu.navigationMenuPopupClassName).toContain("shadow");
  });
});
